/* From Uiverse.io by escannord  - Tags: simple, material design, radio, payment */
.__UIV_SCOPE__ .radio-input input {
  display: none;
}

.__UIV_SCOPE__ .radio-input label {
  --border-color: #a1b0d8;

  border: 1px solid var(--border-color);
  border-radius: 6px;
  min-width: 5rem;
  margin: 1rem;
  padding: 1rem;
  display: flex;
  justify-content: space-between;
  position: relative;
  align-items: center;
}

.__UIV_SCOPE__ .radio-input input:checked + label {
  --border-color: #2f64d8;
  border-color: var(--border-color);
  border-width: 2px;
}
.__UIV_SCOPE__ .radio-input label:hover {
  --border-color: #2f64d8;
  border-color: var(--border-color);
}

.__UIV_SCOPE__ .radio-input {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-direction: column;
}

.__UIV_SCOPE__ .circle {
  display: inline-block;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background-color: rgb(189, 187, 207);
  margin-right: 0.5rem;
  position: relative;
}

.__UIV_SCOPE__ .radio-input input:checked + label span.circle::before {
  content: "";
  display: inline;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: #2f64d8;
  width: 15px;
  height: 15px;
  border-radius: 50%;
}
.__UIV_SCOPE__ .text {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .price {
  display: flex;
  flex-direction: column;
  text-align: right;
  font-weight: bold;
}

.__UIV_SCOPE__ .small {
  font-size: 10px;
  color: rgb(136, 138, 139);
  font-weight: 100;
}

.__UIV_SCOPE__ .info {
  position: absolute;
  display: inline-block;
  font-size: 11px;
  background-color: rgb(31, 236, 123);
  border-radius: 20px;
  padding: 1px 9px;
  top: 0;
  transform: translateY(-50%);
  right: 5px;
}
